import { cva, type VariantProps } from "class-variance-authority";

/**
 * Live Build button styles: a pill with a 1.5px ink outline and a hard
 * bottom edge that presses down on hover, the site's main call to action
 * look. Applied the same way as buttonVariants, straight onto a link:
 *
 *   <Link href="/about" className={ctaVariants({ size: "xl" })}>Meet the team</Link>
 *
 * This lives outside src/components/ui/ on purpose, that folder is
 * generated by the shadcn CLI and is not hand-edited. buttonVariants is
 * unchanged, so a page that has not been redesigned yet looks as before.
 *
 * Keyboard focus comes from the global :focus-visible rule in
 * globals.css, so there is deliberately no outline-none here.
 */
export const ctaVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-full border-[1.5px] font-semibold whitespace-nowrap select-none transition-[transform,box-shadow,background-color,color] duration-150 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        /** The primary action. Sandy Brown fill, press-down edge. */
        cta: "border-ink bg-sandy text-ink shadow-[0_4px_0_var(--ink)] hover:translate-y-0.5 hover:shadow-[0_2px_0_var(--ink)] active:translate-y-1 active:shadow-none",
        /** Secondary action on a light ground. */
        outline:
          "border-ink text-ink hover:bg-ink hover:text-paper bg-transparent",
        /** Secondary action inside a dark section. */
        outlineOnDark:
          "border-navajo text-navajo hover:bg-navajo hover:text-ink bg-transparent",
      },
      size: {
        md: "h-11 px-5 text-[15px]",
        lg: "h-12 px-6 text-base",
        xl: "h-14 px-8 text-lg",
      },
    },
    defaultVariants: {
      variant: "cta",
      size: "lg",
    },
  },
);

export type CtaVariantProps = VariantProps<typeof ctaVariants>;
